// Package meter 提供本地运行的订阅、用量与账单能力。
//
// 使用 NewService（或可注入时钟的 NewServiceWithClock）得到一个并发安全的
// 内存服务，典型流程为：
//
//	s := meter.NewService()
//	_ = s.CreateAccount("acct-1")
//	_ = s.CreatePlan(meter.Plan{
//	    ID: "plan-1", MonthlyFee: 1000, IncludedUnits: 100,
//	    OveragePrice: 5, TaxRateBasisPoints: 600,
//	})
//	_ = s.Subscribe("acct-1", "plan-1", time.Now().UTC())
//	_, _ = s.RecordEvent(meter.Event{
//	    AccountID: "acct-1", EventID: "evt-1",
//	    At: time.Now().UTC(), Quantity: 120,
//	})
//
// 规则摘要：
//   - 金额与用量均为非负 int64，金额单位为分；税率为万分比且取值 [0,10000]。
//   - 账户、套餐标识唯一；缺失引用、负数或非法税率的请求失败且不改已有记录。
//   - 开通订阅时保存套餐条件快照，之后修改套餐不影响该订阅计费；每账户一份
//     当前有效订阅。允许提前登记开通时刻晚于当前时刻的订阅：在实际开通时刻
//     到达前，状态查询显示未生效（Subscribed 为 false、CurrentTerms 为零值、
//     无待换套餐安排与待取消终止时刻），再次开通按已有订阅拒绝，安排换套餐、
//     登记取消返回订阅尚未生效的错误；查询既不删除也不提前激活该登记。生效
//     以实际开通时刻为界（同一瞬间结果与时区无关），不按开通月份提前生效，
//     到达后直接查询即显示登记时保存的完整套餐条件，等待期间修改套餐定义不
//     改变它。旧订阅终止后登记未来重新开通时，两段之间的空档同样不显示生效
//     套餐，历史用量与账单继续可查。
//   - 账期为 UTC 自然月，事件按发生时刻归期；时刻必须属于某段实际订阅期间
//     （开通时刻计入、终止时刻不计入），空档期间与晚于当前时刻的事件拒绝；
//     订阅终止后仍可补报旧订阅期间且尚未出账的用量。
//   - 事件/付款标识在账户内去重：完全相同的重报返回原结果（取消、重新开通后
//     亦然），关键信息不同报冲突。付款重报不再次登记，其返回的余额与付清状态
//     为该笔付款首次成功登记完成时的历史结果，不随后续付款或账单当前状态变化；
//     账单查询与账户状态中的余额始终反映当前状态。
//   - 已出账月份拒绝新事件（已接收事件的重报仍成功，到期欠费时新增仍拒绝）；
//     账单只能为某段订阅实际覆盖且已结束的月份生成，完全无订阅的空档月份出账
//     失败；重复出账得到同一张，金额与用量固定、付款状态可变。
//   - 可安排从下一个 UTC 自然月起换用另一套餐（升级、降级规则相同）：成功时锁定
//     目标套餐完整条件快照并返回生效账期；安排当月仍按旧套餐收完整月费、给完整
//     额度，不按天补差、不迁移用量。每账户至多一条待生效安排，同一目标重复安排
//     返回原安排不重新取价，另一目标则替换；生效前可取消，无安排时取消也成功。
//     到生效月月初零点自动生效，无需上报用量或出账；每张账单始终按该账期当时
//     适用的条件计费，历史账单不被后续切换覆盖。欠费停用期间可安排/取消但不
//     清欠、不解停，结清后按原规则恢复。
//   - 可登记按月取消订阅（CancelSubscription）：仅订阅已生效时可取消，欠费停用
//     不妨碍取消也不免除债务；终止时刻为请求时刻的下一个 UTC 自然月月初并在
//     结果中返回，当月仍按完整月费与额度计费、不按天退款。重复取消始终返回原
//     终止时刻不后移；生效前可用 UndoCancelSubscription 撤回（无取消安排时撤回
//     也成功），终止后撤回失败。登记取消会清除尚未生效的换套餐安排，等待取消
//     期间拒绝新的换套餐安排，撤回取消不恢复被清除的安排；恰在换套餐生效的
//     月初登记取消时，先承认该次切换，取消从再下一月生效。等待取消期间状态
//     仍显示有有效订阅并展示终止时刻；到达终止时刻即无有效订阅、无当前套餐与
//     待切换，历史用量与账单继续可查，且无需上报用量或生成账单。
//   - 终止后可通过原 Subscribe 入口重新开通：开通时刻不得早于上次终止时刻，
//     新订阅保存重新开通当时的套餐条件，当月仍收完整月费、给完整额度；有尚未
//     终止的订阅时拒绝再次开通。重新开通不重置账户内事件与付款标识、不清除旧
//     欠费；结清债务只解除欠费停用，不复活已取消的订阅。支持多次取消与重新
//     开通，旧月份的归属与计价不被后来订阅覆盖。
//   - EstimateCurrentBill 可在月份尚未结束、尚未出账时查询当前 UTC 自然月
//     截至查询时刻的预计账单，结果以 Estimated 恒为 true 明确标为预估。
//     预估沿用正式出账的同一套计价：订阅保存的当月套餐条件快照、完整月费
//     与完整额度（月中开通不按天折算）、超额按快照单价、税额以月费与超额
//     费用之和为基数按万分比四舍五入到分；没有任何用量时累计与超额为零，
//     月费与税额照常计算。尚未生效的换套餐安排不提前混入，到达生效月月初
//     后直接查询即用安排接受时锁定的条件，不依赖先上报用量。查询是纯读
//     操作：不保存正式账单、不关闭当月、不产生欠费、不改变已有账单的金额
//     与付款状态，也不解除欠费停用；已登记按月取消但未到终止时刻、以及因
//     欠费暂停接收新用量但订阅仍生效的账户都可查询。金额超出非负 int64
//     时返回 ErrOverflow，不返回部分金额。账户不存在、从未开通或订阅已
//     终止、提前登记但开通时刻未到分别返回 ErrAccountNotFound、
//     ErrSubscriptionNotFound、ErrSubscriptionNotActivated。
//   - 付款截止为账期结束后七天，支持分次付款；到期仍有余额则停用，结清后恢复。
//     Subscribed 与停用分别表示订阅是否生效与是否存在到期未结清账单：等待开通
//     不清除旧欠费，订阅未生效期间仍可能显示停用；结清旧欠费只更新付款及停用
//     结果，不让未来订阅提前生效。
//   - 用量或金额累计溢出 int64 时请求失败，不留下部分结果。
package meter

// Ready 表示基线可以运行。
func Ready() bool { return true }

package meter

import "time"

// Plan 是套餐的当前定义。修改定义只影响之后新保存的条件快照：之后开通的
// 订阅与之后新接受的换套餐安排按修改后的定义取得条件；已开通订阅保存的
// 快照与已接受安排锁定的条件不被改写。
type Plan struct {
	// ID 套餐唯一标识，不可为空。
	ID string
	// MonthlyFee 月费，单位为分，非负。
	MonthlyFee int64
	// IncludedUnits 每月包含用量，非负。
	IncludedUnits int64
	// OveragePrice 超出部分每单位价格（分/单位），非负。
	OveragePrice int64
	// TaxRateBasisPoints 税率，万分比，取值 [0, 10000]。
	TaxRateBasisPoints int64
}

// PlanTerms 是开通订阅或接受换套餐安排时保存的套餐条件快照。
// 之后修改套餐定义不影响已保存快照的计费。
type PlanTerms struct {
	PlanID             string
	MonthlyFee         int64
	IncludedUnits      int64
	OveragePrice       int64
	TaxRateBasisPoints int64
}

func termsOf(p Plan) PlanTerms {
	return PlanTerms{
		PlanID:             p.ID,
		MonthlyFee:         p.MonthlyFee,
		IncludedUnits:      p.IncludedUnits,
		OveragePrice:       p.OveragePrice,
		TaxRateBasisPoints: p.TaxRateBasisPoints,
	}
}

// Subscription 是一份有效订阅。每个账户只允许一份。
type Subscription struct {
	AccountID string
	// PlanID 开通时所依据的套餐标识。
	PlanID string
	// Terms 开通时刻保存的套餐条件快照。
	Terms PlanTerms
	// ActivatedAt 开通时刻，UTC。用量事件不得早于该时刻。
	ActivatedAt time.Time
}

// PlanChange 是一条尚未生效的换套餐安排。
type PlanChange struct {
	// TargetPlanID 目标套餐标识。
	TargetPlanID string
	// Terms 安排被接受时锁定的目标套餐完整条件快照；
	// 之后修改套餐定义不影响本安排。
	Terms PlanTerms
	// EffectivePeriod 生效账期：安排被接受时的下一个 UTC 自然月。
	EffectivePeriod Month
}

// PlanChangeResult 是换套餐安排成功提交的结果。
type PlanChangeResult struct {
	// Created 为 true 表示本次新建或替换了安排；
	// 为 false 表示目标套餐与已有安排相同，返回原安排，未重新取价。
	Created bool
	// Change 安排内容：目标套餐完整计费条件与生效账期。
	Change PlanChange
}

// SubscriptionCancellation 是一次按月取消订阅安排。
type SubscriptionCancellation struct {
	// EndAt 终止时刻（UTC）：取消请求时刻的下一个 UTC 自然月月初零点。
	// 终止时刻计入空档，不计入订阅期间。
	EndAt time.Time
}

// CancelSubscriptionResult 是取消订阅请求的结果。
type CancelSubscriptionResult struct {
	// Cancelled 为 true 表示本次新登记了取消安排；
	// 为 false 表示此前已安排取消，本次原样返回原终止时刻，不后移期限。
	Cancelled bool
	// Cancellation 取消安排内容。
	Cancellation SubscriptionCancellation
}

// termsEntry 是订阅条件历史中的一条：自 EffectivePeriod（含）起适用 Terms。
type termsEntry struct {
	effective Month
	terms     PlanTerms
}

// Event 是一条用量事件。
type Event struct {
	// AccountID 所属账户。
	AccountID string
	// EventID 事件标识，在同一账户内去重；不同账户可复用。
	EventID string
	// At 事件发生时刻，按此时刻归入账期（UTC 自然月）。
	At time.Time
	// Quantity 数量，非负。
	Quantity int64
}

// EventResult 是用量上报的结果。
type EventResult struct {
	// Accepted 为 true 表示该事件本次被接收并累计；
	// 为 false 表示这是此前已接收事件的完全相同重报，未再次累计。
	Accepted bool
	// Period 事件归入账期。
	Period Month
}

// Month 标识一个 UTC 自然月账期。
type Month struct {
	Year  int
	Month time.Month
}

// MonthOf 返回时刻 t（UTC）所在账期。
func MonthOf(t time.Time) Month {
	u := t.UTC()
	return Month{Year: u.Year(), Month: u.Month()}
}

// Start 返回账期开始时刻（UTC，当月 1 日 00:00:00）。
func (m Month) Start() time.Time {
	return time.Date(m.Year, m.Month, 1, 0, 0, 0, 0, time.UTC)
}

// End 返回账期结束时刻（次月 1 日 00:00:00 UTC），即下月账期开始。
func (m Month) End() time.Time {
	return m.Start().AddDate(0, 1, 0)
}

// Before 报告 m 是否早于 other。
func (m Month) Before(other Month) bool {
	if m.Year != other.Year {
		return m.Year < other.Year
	}
	return m.Month < other.Month
}

// String 返回 YYYY-MM 形式。
func (m Month) String() string {
	return m.Start().Format("2006-01")
}

// Bill 是一个账期的账单。出账后金额与用量明细固定，付款状态可继续变化。
type Bill struct {
	AccountID string
	Period    Month
	// Terms 出账采用的套餐条件：该账期当时适用的条件快照
	// （开通快照或某次已生效换套餐安排锁定的快照）。
	Terms PlanTerms
	// TotalUsage 账期内总用量。
	TotalUsage int64
	// IncludedUnits 包含额度。
	IncludedUnits int64
	// OverageUnits 超额用量 = max(0, TotalUsage - IncludedUnits)。
	OverageUnits int64
	// MonthlyFee 月费（分）。
	MonthlyFee int64
	// OverageFee 超额费用（分）。
	OverageFee int64
	// Tax 税额（分），对月费与超额费用之和按万分比四舍五入。
	Tax int64
	// TotalDue 应付总额（分）= MonthlyFee + OverageFee + Tax。
	TotalDue int64
	// Paid 已付金额（分）。
	Paid int64
	// Balance 剩余应付（分）= TotalDue - Paid。
	Balance int64
	// Settled 是否已付清；零金额账单出账时即为 true。
	Settled bool
	// DueAt 付款截止时刻：账期结束后七天（UTC）。
	DueAt time.Time
}

// EstimatedBill 是账期尚未结束时按查询时刻已接收用量试算的预计账单。
// 它只是一次不落库的预估：不会保存为正式账单、不会关闭当月、不会产生欠费，
// 也不改变任何已有账单的金额与付款状态；同月再次查询会反映其间新增的累计
// 用量。账期结束后正式出账（CreateBill）的结果可能因继续接收用量而与本
// 预估不同——没有新增用量时，各项金额与正式出账一致。
type EstimatedBill struct {
	AccountID string
	// Estimated 恒为 true，用以与正式账单明确区分：本结果是预估，
	// 不代表账期已结束或已经出账。
	Estimated bool
	// Period 预估账期：查询时刻所在的 UTC 自然月。
	Period Month
	// Terms 本账期当前适用的完整套餐条件快照（与正式出账同源）：
	// 开通保存的快照，或已到生效月月初、已实际落入条件时间线的
	// 换套餐快照；尚未生效的换套餐安排不会混入。
	Terms PlanTerms
	// TotalUsage 截至查询时刻该账期已接收的累计用量；没有任何用量时为 0。
	TotalUsage int64
	// IncludedUnits 套餐快照中的完整包含额度；月中开通也按整月提供，不折算。
	IncludedUnits int64
	// OverageUnits 超额用量 = max(0, TotalUsage - IncludedUnits)。
	OverageUnits int64
	// MonthlyFee 完整月费（分）；月中开通也按整月收取，不按天折算。
	MonthlyFee int64
	// OverageFee 超额费用（分）= OverageUnits × Terms.OveragePrice。
	OverageFee int64
	// Tax 税额（分），对月费与超额费用之和按万分比四舍五入。
	Tax int64
	// EstimatedTotalDue 预计应付金额（分）= MonthlyFee + OverageFee + Tax。
	EstimatedTotalDue int64
}

// Payment 是一次本地付款登记记录。
type Payment struct {
	AccountID string
	// PaymentID 付款标识，在同一账户内去重。
	PaymentID string
	// Period 付款所属账期（账单）。
	Period Month
	// Amount 付款金额（分），大于零且不超过账单当时余额。
	Amount int64
}

// PaymentResult 是付款登记结果。
type PaymentResult struct {
	// Registered 为 true 表示本次实际登记；false 表示完全相同重报。
	Registered bool
	Payment    Payment
	// BillBalance 登记后账单余额。
	BillBalance int64
	// Settled 登记后账单是否已付清。
	Settled bool
}

// Usage 是某个账期的累计用量查询结果。
type Usage struct {
	Period Month
	// Total 该账期已累计用量（出账后也保持固定）。
	Total int64
}

// AccountStatus 是账户当前状态查询结果。
type AccountStatus struct {
	AccountID string
	// Subscribed 当前是否有已实际生效的订阅。
	// 提前登记但开通时刻尚未到达的订阅不计入：以实际开通时刻为界，不按开通
	// 月份提前生效（开通当日凌晨仍为 false，到达开通时刻才为 true）。
	// 含已安排取消、尚未到终止时刻的等待期；到达终止时刻后即使没有上报用量
	// 或生成账单，也立即变为 false。
	Subscribed bool
	// Suspended 是否因到期欠费被停用（结清全部到期欠费账单后恢复；
	// 结清债务只解除停用，不复活已取消的订阅，也不让等待开通的订阅提前
	// 生效；等待开通本身不清除旧欠费，Subscribed 为 false 时仍可能停用）。
	Suspended bool
	// CurrentTerms 当前账期实际生效的套餐条件；无已生效订阅（含等待开通
	// 期间）时为零值。到达生效月份月初零点后，无需任何操作即为换套餐后
	// 的条件。
	CurrentTerms PlanTerms
	// PendingChange 尚未生效的换套餐安排；没有安排时为 nil。
	// 订阅未生效期间不允许安排，故等待开通时必为 nil。
	// 登记取消时会清除待生效安排，等待取消期间拒绝新安排。
	PendingChange *PlanChange
	// ScheduledEnd 已安排的订阅终止时刻（下一个 UTC 自然月月初）；
	// 未安排取消、等待开通期间或终止已发生时为 nil。等待取消期间
	// Subscribed 仍为 true。
	ScheduledEnd *time.Time
	// MonthlyUsage 各账期累计用量，按账期先后排列。
	MonthlyUsage []Usage
	// Bills 已生成账单的余额与付清状态，按账期先后排列。
	Bills []BillSummary
}

// BillSummary 是账单的付款状态摘要。
type BillSummary struct {
	Period   Month
	TotalDue int64
	Paid     int64
	Balance  int64
	Settled  bool
	DueAt    time.Time
}

package meter

import (
	"errors"
	"fmt"
)

// 业务错误。请求失败时通过 errors.Is 可判定具体原因。
var (
	// ErrInvalidArgument 表示参数非法：空标识、负数、税率越界或非法账期等。
	ErrInvalidArgument = errors.New("meter: invalid argument")
	// ErrOverflow 表示累计用量或金额超出 int64 范围。
	ErrOverflow = errors.New("meter: overflow")

	// ErrAccountExists 账户标识已存在。
	ErrAccountExists = errors.New("meter: account already exists")
	// ErrAccountNotFound 账户不存在。
	ErrAccountNotFound = errors.New("meter: account not found")

	// ErrPlanExists 套餐标识已存在。
	ErrPlanExists = errors.New("meter: plan already exists")
	// ErrPlanNotFound 套餐不存在。
	ErrPlanNotFound = errors.New("meter: plan not found")

	// ErrSubscriptionExists 该账户已有一份有效订阅。
	ErrSubscriptionExists = errors.New("meter: subscription already exists")
	// ErrSubscriptionNotFound 该账户尚未开通订阅。
	ErrSubscriptionNotFound = errors.New("meter: subscription not found")
	// ErrSubscriptionNotActivated 订阅开通时刻尚未到达。
	ErrSubscriptionNotActivated = errors.New("meter: subscription not activated")
	// ErrPlanChangeSamePlan 换套餐安排的目标套餐与当前生效套餐相同。
	ErrPlanChangeSamePlan = errors.New("meter: plan change target is current plan")
	// ErrPlanChangeNotFound 没有待生效的换套餐安排。
	ErrPlanChangeNotFound = errors.New("meter: plan change not found")
	// ErrPlanChangeWhileCancelling 等待取消期间拒绝新的换套餐安排。
	ErrPlanChangeWhileCancelling = errors.New("meter: plan change rejected while cancellation pending")
	// ErrResubscribeBeforeEnd 重新开通时刻早于上次订阅终止时刻。
	ErrResubscribeBeforeEnd = errors.New("meter: resubscribe before previous end time")

	// ErrEventConflict 事件标识相同但时刻或数量不同。
	ErrEventConflict = errors.New("meter: event conflict")
	// ErrEventBeforeSubscription 事件发生时刻早于订阅开通时刻。
	ErrEventBeforeSubscription = errors.New("meter: event before subscription")
	// ErrEventInFuture 事件发生时刻晚于当前时刻。
	ErrEventInFuture = errors.New("meter: event in the future")
	// ErrMonthBilled 该账期已出账，拒绝首次出现的新事件。
	ErrMonthBilled = errors.New("meter: month already billed")
	// ErrSuspended 账户因到期欠费被停用，拒绝新用量。
	ErrSuspended = errors.New("meter: account suspended")

	// ErrBillNotFound 指定账期尚未生成账单。
	ErrBillNotFound = errors.New("meter: bill not found")
	// ErrBillBeforeSubscription 只能为开通当月及以后生成账单。
	ErrBillBeforeSubscription = errors.New("meter: bill period before subscription")
	// ErrBillMonthNotEnded 只能为已经结束的月份生成账单。
	ErrBillMonthNotEnded = errors.New("meter: bill period has not ended")

	// ErrPaymentConflict 付款标识相同但账单或金额不同。
	ErrPaymentConflict = errors.New("meter: payment conflict")
	// ErrPaymentExceedsBalance 付款金额大于账单当前余额。
	ErrPaymentExceedsBalance = errors.New("meter: payment exceeds balance")
)

func invalidf(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalidArgument, fmt.Sprintf(format, args...))
}

package meter_test

import (
	"errors"
	"fmt"
	"time"

	"github.com/descikazuyq/subscription-meter/meter"
)

// ExampleService_lateBilling 演示“延迟出账”：账期结束一段时间后才生成账单时，
// 付款截止时刻与账户停用行为如何变化。示例只使用 meter 的公开入口，并通过
// NewServiceWithClock 把当前时刻固定在 2026-02-10 00:00 UTC，因此无论实际
// 运行日期为何，输出都固定，不必等到某个真实日期。
//
// 账户 acct-late 持有一份持续有效的订阅：2026-01-01 00:00 UTC 开通，套餐
// 月费 1000 分、无超额、无税，账户没有其他账单。2026-02-10 才为一月出账：
// 付款截止仍是 2026-02-08 00:00 UTC——七天期限从账期结束（2026-02-01
// 00:00 UTC）算起，晚出账不会顺延。截止时刻本身已属于到期：当前时刻已过
// 截止，账单应付与余额都是 1000 分、尚未结清，因此出账后直接查询即显示
// 欠费停用；订阅本身仍有效，当前套餐条件保持原样。
//
// 停用期间上报属于尚未出账的二月的新用量会被拒绝（ErrSuspended），且拒收
// 不消耗事件标识。登记 1000 分本地付款后，一月账单已付 1000 分、余额为零、
// 已结清，账户解除停用，原订阅继续有效；再次提交刚才被拒绝的事件即作为
// 首次接收，二月累计变为 3。付款不改变一月账单原有的应付金额与截止时刻。
func ExampleService_lateBilling() {
	const (
		accountID = "acct-late"
		jan1st    = "2026-01-01T00:00:00Z"
		now       = "2026-02-10T00:00:00Z"
	)
	jan := meter.MonthOf(mustParseTime(jan1st))
	feb := meter.MonthOf(mustParseTime(now))

	// 把“当前时刻”固定在 2026-02-10 00:00 UTC：2026-01 账期早已结束，
	// 此时才为它出账，即“延迟出账”。
	s := meter.NewServiceWithClock(func() time.Time {
		return mustParseTime(now)
	})

	if err := s.CreateAccount(accountID); err != nil {
		panic(err)
	}
	// 套餐月费恰好 1000 分、无超额、无税：账单 TotalDue 就是 1000 分。
	if err := s.CreatePlan(meter.Plan{
		ID:                 "plan1000",
		MonthlyFee:         1000,
		IncludedUnits:      0,
		OveragePrice:       0,
		TaxRateBasisPoints: 0,
	}); err != nil {
		panic(err)
	}
	// 订阅自 2026-01-01 00:00 UTC 起持续有效，不取消、不换套餐。
	if err := s.Subscribe(accountID, "plan1000", mustParseTime(jan1st)); err != nil {
		panic(err)
	}

	// 出账前查询：没有其他欠款，账户未停用，订阅有效。
	st, err := s.Status(accountID)
	if err != nil {
		panic(err)
	}
	fmt.Printf("before bill subscribed=%t suspended=%t planID=%s monthlyFee=%d\n",
		st.Subscribed, st.Suspended, st.CurrentTerms.PlanID, st.CurrentTerms.MonthlyFee)

	// 2026-02-10 才为 2026-01 出账。付款截止时刻仍是账期结束后七天，
	// 即 2026-02-08 00:00 UTC：从账期结束算起，晚出账不顺延。
	// 当前时刻已过截止，账单余额 1000 分未结清。
	bill, err := s.CreateBill(accountID, jan)
	if err != nil {
		panic(err)
	}
	fmt.Printf("bill        period=%s totalDue=%d balance=%d settled=%t dueAt=%s\n",
		bill.Period, bill.TotalDue, bill.Balance, bill.Settled,
		bill.DueAt.Format(time.RFC3339))

	// 出账后直接查询：因一月账单到期未结清而欠费停用；订阅本身仍有效，
	// 当前套餐条件保持原样。
	st, err = s.Status(accountID)
	if err != nil {
		panic(err)
	}
	fmt.Printf("after bill  subscribed=%t suspended=%t planID=%s monthlyFee=%d\n",
		st.Subscribed, st.Suspended, st.CurrentTerms.PlanID, st.CurrentTerms.MonthlyFee)

	// 上报一条发生在当前时刻、数量为 3、属于尚未出账的二月的新用量：
	// 因欠费停用被拒绝（ErrSuspended）。拒收不消耗事件标识 e1。
	_, err = s.RecordEvent(meter.Event{
		AccountID: accountID,
		EventID:   "e1",
		At:        mustParseTime(now),
		Quantity:  3,
	})
	fmt.Printf("event e1    errSuspended=%t\n", errors.Is(err, meter.ErrSuspended))

	// 被拒收的事件没有累计：二月用量仍为零。
	usage, err := s.MonthlyUsage(accountID, feb)
	if err != nil {
		panic(err)
	}
	fmt.Printf("usage       period=%s total=%d\n", usage.Period, usage.Total)

	// 登记 1000 分本地付款，结清一月账单。付款只减少余额，不改变账单
	// 原有的应付金额与截止时刻。
	pay, err := s.RecordPayment(accountID, "pay-jan", jan, 1000)
	if err != nil {
		panic(err)
	}
	fmt.Printf("payment     registered=%t paymentID=%s amount=%d billBalance=%d settled=%t\n",
		pay.Registered, pay.Payment.PaymentID, pay.Payment.Amount, pay.BillBalance, pay.Settled)

	// 查询一月账单：已付 1000 分、余额为零、已结清；应付仍是 1000 分，
	// 截止时刻仍是 2026-02-08 00:00 UTC。
	current, err := s.GetBill(accountID, jan)
	if err != nil {
		panic(err)
	}
	fmt.Printf("get bill    totalDue=%d paid=%d balance=%d settled=%t dueAt=%s\n",
		current.TotalDue, current.Paid, current.Balance, current.Settled,
		current.DueAt.Format(time.RFC3339))

	// 结清全部到期欠费后账户解除停用，原订阅继续有效，套餐条件不变。
	st, err = s.Status(accountID)
	if err != nil {
		panic(err)
	}
	fmt.Printf("after pay   subscribed=%t suspended=%t planID=%s monthlyFee=%d\n",
		st.Subscribed, st.Suspended, st.CurrentTerms.PlanID, st.CurrentTerms.MonthlyFee)

	// 再次提交刚才被拒绝的事件 e1：拒收没有占用事件标识，本次作为
	// 首次接收，归入 2026-02。
	ev, err := s.RecordEvent(meter.Event{
		AccountID: accountID,
		EventID:   "e1",
		At:        mustParseTime(now),
		Quantity:  3,
	})
	if err != nil {
		panic(err)
	}
	fmt.Printf("event e1    accepted=%t period=%s\n", ev.Accepted, ev.Period)

	// 二月累计变为 3。
	usage, err = s.MonthlyUsage(accountID, feb)
	if err != nil {
		panic(err)
	}
	fmt.Printf("usage       period=%s total=%d\n", usage.Period, usage.Total)

	// Output:
	// before bill subscribed=true suspended=false planID=plan1000 monthlyFee=1000
	// bill        period=2026-01 totalDue=1000 balance=1000 settled=false dueAt=2026-02-08T00:00:00Z
	// after bill  subscribed=true suspended=true planID=plan1000 monthlyFee=1000
	// event e1    errSuspended=true
	// usage       period=2026-02 total=0
	// payment     registered=true paymentID=pay-jan amount=1000 billBalance=0 settled=true
	// get bill    totalDue=1000 paid=1000 balance=0 settled=true dueAt=2026-02-08T00:00:00Z
	// after pay   subscribed=true suspended=false planID=plan1000 monthlyFee=1000
	// event e1    accepted=true period=2026-02
	// usage       period=2026-02 total=3
}

## 延迟出账

账单不一定要在账期刚结束时生成：`CreateBill` 可以为任何已经结束且被
某段订阅覆盖的账期出账，哪怕账期结束已过去一段时间。需要注意两点：

- **付款截止时刻不顺延。** `DueAt` 始终是账期结束后七天（UTC），从账期
  结束时刻算起，与何时调用 `CreateBill` 无关。例如 2026-01 账期于
  2026-02-01 00:00 UTC 结束，无论 2 月 1 日还是 2 月 10 日才出账，
  截止时刻都是 2026-02-08 00:00 UTC。截止时刻本身已属于到期：只要
  账单仍有余额，到达该瞬间账户即被停用；零应付且出账即结清的账单不会
  造成欠费停用。
- **账户能否继续接收用量取决于停用状态。** 出账时若截止时刻已过且账单
  未结清，账户立即进入欠费停用，`RecordEvent` 对新事件返回
  `ErrSuspended`；停用只拒绝新用量，订阅本身仍然有效，当前套餐条件
  保持原样，历史用量与账单继续可查。被拒收的事件不消耗事件标识，结清
  全部到期欠费后账户恢复，同一标识可再次提交并按首次接收。登记付款只
  减少账单余额，不改变账单原有的应付金额与截止时刻。

下面的示例只用公开入口即可运行：通过 `NewServiceWithClock` 把当前时刻
固定在 2026-02-10 00:00 UTC，再为一月出账。账户 `acct-late` 持有一份
持续有效的订阅（2026-01-01 00:00 UTC 开通，套餐月费 1000 分，超额单价
与税率均为零，账户没有其他账单）。示例依次展示：出账前账户未停用；
延迟出账后截止时刻仍为 2026-02-08 00:00 UTC、账单应付与余额都是
1000 分且尚未结清，账户因此欠费停用而订阅仍有效；属于尚未出账的二月
的新用量被拒且二月累计仍为零；登记 1000 分本地付款后一月账单结清、
账户解除停用；再次提交刚才被拒绝的事件作为首次接收，二月累计变为 3。
该示例以 Example 测试形式保存在 `meter/late_billing_example_test.go`，
`go test ./...` 会校验其输出：

