26	//	           月费 2000、包含 20、超额单价 50、税率 600（万分比）。
27	//	           随后把 plan-new 的当前定义改为 5000/5/300/1000，新订阅不受影响。
28	//	           恰在开通瞬间上报数量 25 的事件：首次接收、归入三月；
29	//	           另一条发生在 3 月 14 日的事件即便在重新开通之后提交，仍返回
30	//	           ErrEventBeforeSubscription，不增加三月累计。
31	//	2026-04-01 三月结束后首次出账：总用量 25、超额 5、超额费 250、税 135、
32	//	           应付 2385，条件取重新开通时保存的 2000/20/50/600 完整快照；
33	//	           二月仍是 ErrBillBeforeSubscription/ErrBillNotFound，一月旧账单
34	//	           金额与付款结果保持原样。
35	
36	// TestMidMonthResubscribeFirstMonthBilledWithFullSavedTerms 端到端回归上述主线。
37	func TestMidMonthResubscribeFirstMonthBilledWithFullSavedTerms(t *testing.T) {
38		s, clk := newTestService(utc(2026, 1, 1, 0, 0))
39	
40		oldDef := planDef("plan-old", 1000, 10, 100, 1000)
41		newDefAtResubscribe := planDef("plan-new", 2000, 20, 50, 600)
42		newDefUpdated := planDef("plan-new", 5000, 5, 300, 1000)
43		oldTerms := termsOf(oldDef)
44		newSavedTerms := termsOf(newDefAtResubscribe)
45		updatedTerms := termsOf(newDefUpdated)
46	
47		mustPlan(t, s, oldDef)
48		mustPlan(t, s, newDefAtResubscribe)
49		mustAccount(t, s, "u")
50		mustSubscribe(t, s, "u", "plan-old", utc(2026, 1, 1, 0, 0))
51	
52		// 一月用量 15：超出旧套餐包含的 10 单位，超额 5×100=500。
53		clk.t = utc(2026, 1, 10, 0, 0)
54		if r, err := s.RecordEvent(Event{
55			AccountID: "u", EventID: "e-jan", At: utc(2026, 1, 10, 0, 0), Quantity: 15,
56		}); err != nil || !r.Accepted || r.Period != jan(2026) {
57			t.Fatalf("january usage: %+v %v", r, err)
58		}
59	
60		// 一月中旬登记按月取消：终止时刻 2026-02-01 00:00，一月仍按完整月计费。
61		clk.t = utc(2026, 1, 15, 12, 0)
62		cancelRes := mustCancel(t, s, "u")
63		if !cancelRes.Cancelled || !cancelRes.Cancellation.EndAt.Equal(utc(2026, 2, 1, 0, 0)) {
64			t.Fatalf("cancel result = %+v, want end 2026-02-01", cancelRes)
65		}
66	
67		// 2026-02-01 终止时刻到达：无有效订阅；一月账期恰好结束，出账并结清，
68		// 保证三月接收用量时没有欠费停用。
69		clk.t = utc(2026, 2, 1, 0, 0)
70		if st, _ := s.Status("u"); st.Subscribed || st.CurrentTerms != (PlanTerms{}) {
71			t.Fatalf("status at termination = %+v, want unsubscribed zero terms", st)
72		}
73		janBill, err := s.CreateBill("u", jan(2026))
74		if err != nil {
75			t.Fatalf("create january bill: %v", err)
76		}
77		// 旧账单金额与新套餐条件明显不同，三月账单若错用旧订阅会在这里对不上：
78		// 1000 + 5×100 = 1500，税 150，应付 1650。
79		if janBill.Terms != oldTerms || janBill.TotalUsage != 15 ||
80			janBill.IncludedUnits != 10 || janBill.OverageUnits != 5 ||
81			janBill.MonthlyFee != 1000 || janBill.OverageFee != 500 ||
82			janBill.Tax != 150 || janBill.TotalDue != 1650 ||
83			janBill.Paid != 0 || janBill.Balance != 1650 || janBill.Settled {
84			t.Fatalf("january bill initial = %+v, want plan-old 15/5/500/150/1650 unpaid", janBill)
85		}
86		pay, err := s.RecordPayment("u", "pay-jan", jan(2026), 1650)
87		if err != nil || !pay.Registered || pay.BillBalance != 0 || !pay.Settled {
88			t.Fatalf("settle january bill: %+v %v", pay, err)
89		}
90	
91		// 二月整月空档：二月发生的事件不属任何订阅期间，现有错误拒绝。
92		clk.t = utc(2026, 2, 15, 12, 0)
93		if _, err := s.RecordEvent(Event{
94			AccountID: "u", EventID: "e-feb", At: utc(2026, 2, 10, 0, 0), Quantity: 1,
95		}); !errors.Is(err, ErrEventBeforeSubscription) {
96			t.Fatalf("february gap event = %v, want ErrEventBeforeSubscription", err)
97		}
98	
99		// 三月一日仍处两段订阅之间的空档：二月账期已结束，但不能因之后重新开通
100		// 而补出二月月费，也查询不到二月账单。
101		clk.t = utc(2026, 3, 1, 0, 0)
102		if st, _ := s.Status("u"); st.Subscribed {
103			t.Fatalf("status during march gap = %+v, want unsubscribed", st)
104		}
105		if _, err := s.CreateBill("u", feb(2026)); !errors.Is(err, ErrBillBeforeSubscription) {
106			t.Fatalf("bill february gap = %v, want ErrBillBeforeSubscription", err)
107		}
108		if _, err := s.GetBill("u", feb(2026)); !errors.Is(err, ErrBillNotFound) {
109			t.Fatalf("february bill queryable in gap = %v, want ErrBillNotFound", err)
110		}
111	
112		// 2026-03-15 12:00 月中重新开通另一套餐：保存此刻 plan-new 的完整条件快照。
113		reopenAt := utc(2026, 3, 15, 12, 0)
114		clk.t = reopenAt
115		mustSubscribe(t, s, "u", "plan-new", reopenAt)
116		st, _ := s.Status("u")
117		if !st.Subscribed || st.Suspended {
118			t.Fatalf("status at reopen = %+v, want subscribed and not suspended", st)
119		}
120		if st.CurrentTerms != newSavedTerms {
121			t.Fatalf("terms at reopen = %+v, want saved snapshot %+v", st.CurrentTerms, newSavedTerms)
122		}
123	
124		// 重新开通之后修改该套餐的当前定义：只影响之后新保存的快照，不能改写
125		// 本订阅已经保存的条件。
126		if err := s.UpdatePlan(newDefUpdated); err != nil {
127			t.Fatalf("update plan-new: %v", err)
128		}
129		st, _ = s.Status("u")
130		if st.CurrentTerms != newSavedTerms {
131			t.Fatalf("saved terms overwritten by plan update = %+v, want %+v", st.CurrentTerms, newSavedTerms)
132		}
133		if st.CurrentTerms == updatedTerms {
134			t.Fatalf("current terms must not equal updated definition %+v", updatedTerms)
135		}
136	
137		// 恰在重新开通瞬间（开通时刻计入订阅期间）上报数量 25：首次接收、归入三月。
138		atReopen := Event{
139			AccountID: "u", EventID: "e-mar-at-open",
140			At: reopenAt, Quantity: 25,
141		}
142		r, err := s.RecordEvent(atReopen)
143		if err != nil || !r.Accepted || r.Period != mar(2026) {
144			t.Fatalf("event exactly at reopen instant: %+v %v", r, err)
145		}
146	
147		// 另一条发生在三月十四日（重新开通之前、同一个 UTC 自然月内）的新事件：
148		// 提交时刻账户已经重新开通，但事件时刻不属任何实际订阅期间，必须返回现有
149		// 的 ErrEventBeforeSubscription，不能因“三月可整月出账”而接收。
150		beforeInSameMonth := Event{
151			AccountID: "u", EventID: "e-mar-before-open",
152			At: utc(2026, 3, 14, 0, 0), Quantity: 9,
153		}
154		if _, err := s.RecordEvent(beforeInSameMonth); !errors.Is(err, ErrEventBeforeSubscription) {
155			t.Fatalf("march event before reopen = %v, want ErrEventBeforeSubscription", err)
156		}
157		// 被拒事件不增加三月累计，也不产生二月记录；三月只有开通瞬间的 25。
158		if u, _ := s.MonthlyUsage("u", mar(2026)); u.Total != 25 {
159			t.Fatalf("march usage = %d, want 25", u.Total)
160		}
161		if u, _ := s.MonthlyUsage("u", feb(2026)); u.Total != 0 {
162			t.Fatalf("february usage = %d, want 0", u.Total)
163		}
164		st, _ = s.Status("u")
165		if len(st.MonthlyUsage) != 2 ||
166			st.MonthlyUsage[0] != (Usage{Period: jan(2026), Total: 15}) ||
167			st.MonthlyUsage[1] != (Usage{Period: mar(2026), Total: 25}) {
168			t.Fatalf("monthly usage after reopen = %+v, want [2026-01=15 2026-03=25]", st.MonthlyUsage)
169		}
170	
171		// 拒收不消耗事件标识：同一标识改报订阅期间内、已发生的时刻应被当作全新
172		// 事件接收（若拒收落库，会因时刻/数量不同报 ErrEventConflict）。数量取零，
173		// 不改变三月总用量 25，后续出账仍以 25 为准。
174		reused := Event{
175			AccountID: "u", EventID: "e-mar-before-open",
176			At: reopenAt, Quantity: 0,
177		}
178		r2, err := s.RecordEvent(reused)
179		if err != nil || !r2.Accepted || r2.Period != mar(2026) {
180			t.Fatalf("rejected id must remain usable: %+v %v", r2, err)
181		}
182		if u, _ := s.MonthlyUsage("u", mar(2026)); u.Total != 25 {
183			t.Fatalf("march usage after zero-quantity id reuse = %d, want 25", u.Total)
184		}
185	
186		// 开通瞬间事件的原样重报仍成功但不再次累计。
187		if r3, err := s.RecordEvent(atReopen); err != nil || r3.Accepted || r3.Period != mar(2026) {
188			t.Fatalf("identical replay at reopen: %+v %v", r3, err)
189		}
190		if u, _ := s.MonthlyUsage("u", mar(2026)); u.Total != 25 {
191			t.Fatalf("march usage after replay = %d, want 25", u.Total)
192		}
193	
194		// 三月结束后首次出账：整月按重新开通时保存的完整条件，不按 3/15 起的
195		// 剩余天数缩减。总用量 25、超额 25-20=5、超额费 5×50=250、
196		// 税 (2000+250)×600/10000=135、应付 2385；初始已付 0、余额 2385、未付清。
197		clk.t = utc(2026, 4, 1, 0, 0)
198		marBill, err := s.CreateBill("u", mar(2026))
199		if err != nil {
200			t.Fatalf("create march bill: %v", err)
201		}
202		if marBill.Terms != newSavedTerms {
203			t.Fatalf("march bill terms = %+v, want saved snapshot %+v", marBill.Terms, newSavedTerms)
204		}
205		if marBill.Terms == updatedTerms {
206			t.Fatalf("march bill must not use updated definition %+v", updatedTerms)
207		}
208		if marBill.TotalUsage != 25 || marBill.IncludedUnits != 20 ||
209			marBill.OverageUnits != 5 || marBill.MonthlyFee != 2000 ||
210			marBill.OverageFee != 250 || marBill.Tax != 135 || marBill.TotalDue != 2385 {
211			t.Fatalf("march bill amounts = usage %d included %d over %d fee %d overFee %d tax %d due %d, want 25/20/5/2000/250/135/2385",
212				marBill.TotalUsage, marBill.IncludedUnits, marBill.OverageUnits,
213				marBill.MonthlyFee, marBill.OverageFee, marBill.Tax, marBill.TotalDue)
214		}
215		if marBill.Paid != 0 || marBill.Balance != 2385 || marBill.Settled {
216			t.Fatalf("march bill initial payment state = paid %d balance %d settled %v, want 0/2385/false",
217				marBill.Paid, marBill.Balance, marBill.Settled)
218		}
219		if !marBill.DueAt.Equal(utc(2026, 4, 8, 0, 0)) {
220			t.Fatalf("march bill dueAt = %v, want 2026-04-08", marBill.DueAt)
221		}
222	
223		// 重复出账得到同一张账单。
224		if again, err := s.CreateBill("u", mar(2026)); err != nil || again != marBill {
225			t.Fatalf("march bill not idempotent: %+v %v", again, err)
226		}
227	
228		// 相邻空档月份二月在三月重新开通并出账之后，仍然不能补出月费。
229		if _, err := s.CreateBill("u", feb(2026)); !errors.Is(err, ErrBillBeforeSubscription) {
230			t.Fatalf("february bill after march billed = %v, want ErrBillBeforeSubscription", err)
231		}
232		if _, err := s.GetBill("u", feb(2026)); !errors.Is(err, ErrBillNotFound) {
233			t.Fatalf("february bill queryable after march billed = %v, want ErrBillNotFound", err)
234		}
235	
236		// 三月账单查询与账户状态中的账单摘要展示一致的应付与初始余额；
237		// 账单列表只含一月与三月（空档二月不在其中），当前套餐仍是保存的快照。
238		gotMar, err := s.GetBill("u", mar(2026))
239		if err != nil {
240			t.Fatalf("get march bill: %v", err)
241		}
242		if gotMar.TotalDue != 2385 || gotMar.Balance != 2385 || gotMar.Paid != 0 || gotMar.Settled {
243			t.Fatalf("get march bill state = due %d paid %d balance %d settled %v, want 2385/0/2385/false",
244				gotMar.TotalDue, gotMar.Paid, gotMar.Balance, gotMar.Settled)
245		}
246		st, _ = s.Status("u")
247		if !st.Subscribed || st.CurrentTerms != newSavedTerms {
248			t.Fatalf("status after march bill = %+v, want subscribed with saved snapshot", st.CurrentTerms)
249		}
250		if len(st.Bills) != 2 {
251			t.Fatalf("status bills = %+v, want january and march only", st.Bills)
252		}
253		sumJan, sumMar := st.Bills[0], st.Bills[1]
254		if sumJan.Period != jan(2026) || sumJan.TotalDue != 1650 || sumJan.Paid != 1650 ||
255			sumJan.Balance != 0 || !sumJan.Settled {
256			t.Fatalf("status january summary = %+v, want due 1650 paid 1650 settled", sumJan)
257		}
258		if sumMar.Period != mar(2026) || sumMar.TotalDue != 2385 || sumMar.Paid != 0 ||
259			sumMar.Balance != 2385 || sumMar.Settled {
260			t.Fatalf("status march summary = %+v, want due 2385 balance 2385 unpaid", sumMar)
261		}
262	
263		// 旧账单固定的部分保持原样：套餐快照、用量明细、各项费用、税额、应付总额与
264		// 付款截止都不被重新开通、改价或三月出账改动；付款状态则随结清而变化。
265		gotJan, err := s.GetBill("u", jan(2026))
266		if err != nil {
267			t.Fatalf("get january bill: %v", err)
268		}
269		if gotJan.Terms != janBill.Terms || gotJan.TotalUsage != janBill.TotalUsage ||
270			gotJan.IncludedUnits != janBill.IncludedUnits || gotJan.OverageUnits != janBill.OverageUnits ||
271			gotJan.MonthlyFee != janBill.MonthlyFee || gotJan.OverageFee != janBill.OverageFee ||
272			gotJan.Tax != janBill.Tax || gotJan.TotalDue != janBill.TotalDue ||
273			!gotJan.DueAt.Equal(janBill.DueAt) {
274			t.Fatalf("january bill fixed content changed:\ninitial=%+v\nget    =%+v", janBill, gotJan)
275		}
276		// 原付款原样重报不再次登记，返回首次登记完成时的历史结果（余额 0、已付清）。
277		replay, err := s.RecordPayment("u", "pay-jan", jan(2026), 1650)
278		if err != nil {
279			t.Fatalf("replay january payment: %v", err)
280		}
281		if replay.Registered || replay.Payment != (Payment{
282			AccountID: "u", PaymentID: "pay-jan", Period: jan(2026), Amount: 1650,
283		}) || replay.BillBalance != 0 || !replay.Settled {
284			t.Fatalf("january payment replay = %+v, want not registered historical 0/settled", replay)
285		}
286		gotJan, _ = s.GetBill("u", jan(2026))
287		if gotJan.TotalDue != 1650 || gotJan.Paid != 1650 || gotJan.Balance != 0 || !gotJan.Settled {
288			t.Fatalf("january bill after payment replay = %+v, want unchanged settled 1650", gotJan)
289		}
290	}
291

